1	<#
2	.SYNOPSIS
3	  同步绿洲启元编辑器线上资源到本地 Obsidian Vault
4	.DESCRIPTION
5	  Wiki 同步: 对比线上分类树与本地索引，下载新文章
6	  API 同步:  对比线上文件列表与本地文件，下载新文档
7	.PARAMETER VaultRoot  根目录
8	.PARAMETER DownloadNew 自动下载新 Wiki 文章
9	.PARAMETER UpdateMoc  更新 MOC 计数
10	.PARAMETER SyncApi    对比 API 文档差异
11	.PARAMETER DownloadApi 自动下载缺失的 API 文件
12	#>
13	param(
14	  [string]$VaultRoot = (Resolve-Path "$PSScriptRoot\.."),
15	  [switch]$DownloadNew,
16	  [switch]$UpdateMoc,
17	  [switch]$SyncApi,
18	  [switch]$DownloadApi
19	)
20	
21	$WikiDir = Join-Path $VaultRoot "wiki"
22	$ApiDir = Join-Path $VaultRoot "api"
23	$IndexFile = Join-Path $WikiDir "_index.json"
24	$MocFile = Join-Path $VaultRoot "MOC-总览.md"
25	
26	function Write-Step($m) { Write-Host ">>> $m" -ForegroundColor Cyan }
27	function Write-Success($m) { Write-Host "[OK] $m" -ForegroundColor Green }
28	function Write-Warn($m) { Write-Host "[!] $m" -ForegroundColor Yellow }
29	function Write-Err($m) { Write-Host "[ERR] $m" -ForegroundColor Red }
30	
31	# ============ WIKI ============
32	function Sync-Wiki {
33	  Write-Step "获取线上 Wiki 分类树..."
34	  $lookRes = try {
35	    Invoke-RestMethod "https://developer.gp.qq.com/wikieditor/_api/look-Category" -Method Get -TimeoutSec 15
36	  } catch { Write-Err "无法连接线上 Wiki: $_"; return }
37	  if ($lookRes.code -ne 0) { Write-Err "API 错误: $($lookRes.message)"; return }
38	  $tree = $lookRes.data[0].Body | ConvertFrom-Json
39	
40	  function Extract-Articles($Nodes, $ParentPath = "") {
41	    $result = @()
42	    foreach ($node in $Nodes) {
43	      if ($node.type -eq 1) {
44	        $path = if ($ParentPath) { "$ParentPath > $($node.label)" } else { $node.label }
45	        $result += [PSCustomObject]@{ Id=[int]$node.id; Label=$node.label; Path=$path; IsDraft=if($null-ne$node.isDraft){$node.isDraft}else{$false} }
46	      } elseif ($node.type -eq 0 -and $node.children) {
47	        $cp = if ($ParentPath) { "$ParentPath > $($node.label)" } else { $node.label }
48	        $result += Extract-Articles $node.children $cp
49	      }
50	    }
51	    return $result
52	  }
53	  $onlineArticles = Extract-Articles $tree
54	  Write-Success "线上共 $($onlineArticles.Count) 篇文章"
55	
56	  Write-Step "读取本地索引..."
57	  $localArticles = if (Test-Path $IndexFile) { Get-Content $IndexFile -Raw -Encoding UTF8 | ConvertFrom-Json } else { @() }
58	  Write-Success "本地共 $($localArticles.Count) 篇文章"
59	
60	  $onlineById = @{}; $onlineArticles | ForEach-Object { $onlineById[$_.Id] = $_ }
61	  $localById = @{}; $localArticles | ForEach-Object { $localById[[int]$_.id] = $_ }
62	  $newArticles = $onlineArticles | Where-Object { -not $localById.ContainsKey($_.Id) -and -not $_.IsDraft } | Sort-Object Id
63	  $removedArticles = $localArticles | Where-Object { -not $onlineById.ContainsKey([int]$_.id) }
64	
65	  Write-Host "`n=== Wiki 报告 ===" -ForegroundColor Cyan
66	  Write-Host "线上: $($onlineArticles.Count)  |  本地: $($localArticles.Count)"
67	  if ($newArticles.Count -gt 0) {
68	    Write-Host "[新增] $($newArticles.Count) 篇:" -ForegroundColor Green
69	    $newArticles | ForEach-Object { Write-Host "  ID $($_.Id): $($_.Label)" -ForegroundColor Green }
70	  }
71	  if ($removedArticles.Count -gt 0) {
72	    Write-Host "[删除] $($removedArticles.Count) 篇:" -ForegroundColor Yellow
73	    $removedArticles | ForEach-Object { Write-Host "  ID $($_.id): $($_.label)" -ForegroundColor Yellow }
74	  }
75	  if ($newArticles.Count -eq 0 -and $removedArticles.Count -eq 0) { Write-Host "[OK] 已是最新" -ForegroundColor Green }
76	
77	  if ($DownloadNew -and $newArticles.Count -gt 0) {
78	    Write-Host "`n>>> 下载新文章..." -ForegroundColor Cyan
79	    $downloaded = 0
80	    foreach ($article in $newArticles) {
81	      $id = $article.Id; Write-Host "  [$id] $($article.Label) ... " -NoNewline
82	      try {
83	        $res = Invoke-RestMethod "https://developer.gp.qq.com/wikieditor/_api/query-articles?Id=$id" -Method Get -TimeoutSec 10
84	        if ($res.code -eq 0 -and $res.data.Count -gt 0) {
85	          $data = $res.data[0]
86	          $fileName = $data.Title -replace '[\\/:*?"<>|]', '_'
87	          $filePath = Join-Path $WikiDir "$fileName.md"
88	          @"
89	---
90	title: "$($data.Title)"
91	tags:
92	  - wiki
93	  - 自动同步
94	---
95	$($data.Body)
96	"@ | Out-File $filePath -Encoding UTF8
97	          $localArticles += [PSCustomObject]@{ id=[int]$data.Id; label=$data.Title; path=if($data.Level){$data.Level}else{$data.Title}; file="$fileName.md"; success=$true }
98	          Write-Host "OK" -ForegroundColor Green; $downloaded++
99	        } else { Write-Host "空" -ForegroundColor Yellow }
100	      } catch { Write-Host "失败: $_" -ForegroundColor Red }
101	    }
102	    if ($downloaded -gt 0) {
103	      Write-Step "更新 _index.json..."
104	      $localArticles | ConvertTo-Json -Depth 3 | Out-File $IndexFile -Encoding UTF8
105	      if ($UpdateMoc -and (Test-Path $MocFile)) {
106	        $moc = Get-Content $MocFile -Raw -Encoding UTF8
107	        $match = [regex]::Match($moc, '共 \*\*(\d+)\s*篇\*\*文章')
108	        if ($match.Success) {
109	          $newTotal = [int]$match.Groups[1].Value + $downloaded
110	          $moc = $moc -replace '共 \*\*\d+\s*篇\*\*文章', "共 **${newTotal} 篇**文章"
111	          $today = Get-Date -Format "yyyy-MM-dd"
112	          $moc = $moc -replace '最后更新: \d{4}-\d{2}-\d{2}', "最后更新: $today"
113	          $moc | Out-File $MocFile -Encoding UTF8
114	          Write-Success "MOC 更新完毕"
115	        }
116	        Write-Warn "表格行需手动添加到 MOC"
117	      }
118	    }
119	  }
120	}
