122	# ============ API ============
123	function Sync-Api {
124	  Write-Step "扫描线上 API 文档..."
125	
126	  # 类: tree.json
127	  Write-Host "  获取类文档列表 ... " -NoNewline
128	  $classList = @()
129	  try {
130	    $tree = Invoke-RestMethod "https://developer.gp.qq.com/api/class/list/tree.json" -Method Get -TimeoutSec 15
131	    function Get-Files($Nodes) {
132	      $r = @()
133	      foreach ($node in $Nodes) {
134	        if ($node.Path) {
135	          $name = $node.Name
136	          $subPath = $node.Path -replace '^class/detail/','' -replace '\.json$',''
137	          $r += @{Name=$name; SubPath=$subPath}
138	        }
139	        if ($node.Children -and $node.Children.Count -gt 0 -and $node.Children -is [array]) { $r += Get-Files $node.Children }
140	      }
141	      return $r
142	    }
143	    $classList = Get-Files $tree
144	    Write-Host "$($classList.Count) 个" -ForegroundColor Green
145	  } catch { Write-Host "失败: $_" -ForegroundColor Red }
146	
147	  # 枚举/结构体/全局函数: 目录列表
148	  function Get-Listing($Url, $Label) {
149	    Write-Host "  获取 ${Label}列表 ... " -NoNewline
150	    try {
151	      $r = Invoke-WebRequest $Url -UseBasicParsing -TimeoutSec 30 -Method Get
152	      $m = [regex]::Matches($r.Content, '<a href="([^"]+\.json)"')
153	      $list = $m | ForEach-Object { $n = $_.Groups[1].Value -replace '\.json$',''; @{Name=$n; SubPath=$n} }
154	      Write-Host "$($list.Count) 个" -ForegroundColor Green
155	      return $list
156	    } catch { Write-Host "失败: $_" -ForegroundColor Red; return @() }
157	  }
158	
159	  $enumList   = Get-Listing "https://developer.gp.qq.com/api/cppenum/detail/" "枚举"
160	  $structList = Get-Listing "https://developer.gp.qq.com/api/cppstruct/detail/" "结构体"
161	  $funcList   = Get-Listing "https://developer.gp.qq.com/api/globalfunc/detail/" "全局函数"
162	
163	  # 汇总对比
164	  $apiTypes = @(
165	    @{Name="类文档";  List=$classList;  LocalDir="class\detail";    UrlBase="https://developer.gp.qq.com/api/class/detail"}
166	    @{Name="枚举";    List=$enumList;   LocalDir="cppenum\detail"; UrlBase="https://developer.gp.qq.com/api/cppenum/detail"}
167	    @{Name="结构体";  List=$structList; LocalDir="cppstruct\detail"; UrlBase="https://developer.gp.qq.com/api/cppstruct/detail"}
168	    @{Name="全局函数"; List=$funcList;  LocalDir="globalfunc\detail"; UrlBase="https://developer.gp.qq.com/api/globalfunc/detail"}
169	  )
170	
171	  $totalNew = 0
172	  $results = @()
173	
174	  foreach ($type in $apiTypes) {
175	    $localPath = Join-Path $ApiDir $type.LocalDir
176	    $localMap = @{}
177	    if (Test-Path $localPath) {
178	      Get-ChildItem "$localPath" -Recurse -Filter "*.json" -File | ForEach-Object { $localMap[$_.BaseName] = $true }
179	    }
180	    $found = 0; $newFiles = @()
181	    foreach ($f in $type.List) {
182	      if ($localMap.ContainsKey($f.Name)) { $found++ }
183	      else { $newFiles += $f }
184	    }
185	    $totalNew += $newFiles.Count
186	    $results += @{Name=$type.Name; Online=$type.List.Count; Local=$found; New=$newFiles.Count; NewList=$newFiles; LocalDir=$localPath; UrlBase=$type.UrlBase}
187	    if ($newFiles.Count -gt 0) {
188	      Write-Host "[新增] $($type.Name): $($newFiles.Count)" -ForegroundColor Green
189	      $newFiles | ForEach-Object { Write-Host "  $($_.Name)" -ForegroundColor Green }
190	    }
191	  }
192	
193	  # 下载
194	  if ($DownloadApi -and $totalNew -gt 0) {
195	    Write-Host "`n>>> 下载新 API 文件 ..." -ForegroundColor Cyan
196	    $dl = 0
197	    foreach ($type in $results) {
198	      if ($type.NewList.Count -eq 0) { continue }
199	      foreach ($f in $type.NewList) {
200	        Write-Host "  $($f.Name) ... " -NoNewline
201	        try {
202	          $dir = Split-Path "$($type.LocalDir)\$($f.Name).json" -Parent
203	          if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
204	          Invoke-WebRequest "$($type.UrlBase)/$($f.SubPath).json" -UseBasicParsing -TimeoutSec 15 -OutFile "$($type.LocalDir)\$($f.Name).json"
205	          Write-Host "OK" -ForegroundColor Green; $dl++
206	        } catch { Write-Host "失败: $_" -ForegroundColor Red }
207	      }
208	    }
209	    # 更新搜索索引
210	    $idxPath = Join-Path $ApiDir "_search_index.json"
211	    if (Test-Path $idxPath) {
212	      $idx = Get-Content $idxPath -Raw -Encoding UTF8 | ConvertFrom-Json
213	      $known = @{}; $idx | ForEach-Object { $known[$_.name] = $true }
214	      $typeMap = @{"类文档"="class"; "枚举"="enum"; "结构体"="struct"; "全局函数"="function"}
215	      foreach ($type in $results) {
216	        $t = $typeMap[$type.Name]
217	        foreach ($f in $type.NewList) {
218	          if (-not $known.ContainsKey($f.Name)) {
219	            $idx += [PSCustomObject]@{ name=$f.Name; description=""; type=$t; path="$ApiDir\$($type.LocalDir)\$($f.Name).json"; functions=0; variables=0 }
220	          }
221	        }
222	      }
223	      $idx | ConvertTo-Json -Depth 3 | Out-File $idxPath -Encoding UTF8
224	      Write-Success "搜索索引已更新"
225	    }
226	  }
227	
228	  # 报告
229	  Write-Host "`n=== API 报告 ===" -ForegroundColor Cyan
230	  Write-Host ("{0,-8} | {1,6} | {2,5} | {3,5}" -f "类型", "在线", "本地", "新增") -ForegroundColor Cyan
231	  Write-Host ("--------+--------+-------+------") -ForegroundColor Cyan
232	  $tOnline = 0; $tLocal = 0
233	  foreach ($r in $results) {
234	    Write-Host ("{0,-8} | {1,6} | {2,5} | {3,5}" -f $r.Name, $r.Online, $r.Local, "+$($r.New)")
235	    $tOnline += $r.Online; $tLocal += $r.Local
236	  }
237	  Write-Host ("--------+--------+-------+------") -ForegroundColor Cyan
238	  Write-Host ("{0,-8} | {1,6} | {2,5} | {3,5}" -f "合计", $tOnline, $tLocal, "+$totalNew") -ForegroundColor Cyan
239	}
240	
241	if ($SyncApi) { Sync-Api } else { Sync-Wiki }
